    if s.endswith(' Dept.'):
        return s
    elif m := re_end_dot.search(s):
        return s[:-1]
    return s


def fix_l_in_date(date):
    if 'l' not in date:
        return date
    return re_l_in_date.sub(lambda m: m.group(1).replace('l', '1'), date)

